USE user_ltv_analytics;
CREATE TABLE IF NOT EXISTS users (user_id BIGINT PRIMARY KEY, signup_date DATE NOT NULL, channel VARCHAR(32) NOT NULL, region VARCHAR(32), device VARCHAR(16), age_group VARCHAR(16), acquisition_cost DECIMAL(10,2)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS events (event_id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, event_time DATETIME NOT NULL, event_type VARCHAR(32) NOT NULL, session_duration DECIMAL(10,2) NOT NULL, CONSTRAINT fk_events_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS transactions (order_id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, order_time DATETIME NOT NULL, amount DECIMAL(12,2) NOT NULL, refund_amount DECIMAL(12,2) NOT NULL, product_category VARCHAR(64), CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_snapshots (user_id BIGINT NOT NULL, snapshot_date DATE NOT NULL, tenure_days INT, active_days_7d INT, active_days_30d INT, active_days_90d INT, login_count_30d INT, browse_count_30d INT, search_count_30d INT, cart_count_30d INT, purchase_count_30d INT, purchase_count_90d INT, revenue_30d DECIMAL(12,2), revenue_90d DECIMAL(12,2), days_since_last_active INT, days_since_last_purchase INT, avg_session_duration DECIMAL(12,2), avg_order_value DECIMAL(12,2), purchase_frequency DECIMAL(12,4), historical_ltv DECIMAL(14,2), churn_30d TINYINT, future_90d_revenue DECIMAL(14,2), ltv_label_mature_date DATE, churn_label_mature_date DATE, ltv_split VARCHAR(16), churn_split VARCHAR(16), split VARCHAR(16), PRIMARY KEY(user_id,snapshot_date), CONSTRAINT fk_snapshot_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_predictions (user_id BIGINT NOT NULL, snapshot_date DATE NOT NULL, predicted_ltv DECIMAL(14,2), churn_probability DECIMAL(8,6), customer_segment VARCHAR(64), PRIMARY KEY(user_id,snapshot_date), CONSTRAINT fk_prediction_user FOREIGN KEY(user_id) REFERENCES users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
